//! SYMMETRY sets: permutations of model values.

use std::cmp::Ordering;
use std::collections::{HashMap, HashSet};
use std::sync::Arc;

use tlx_sema::hir::Expr;
use tlx_value::order::cmp_tlc;
use tlx_value::{ops, Sym, Value};

use crate::env::Env;
use crate::error::{EResult, EvalError};
use crate::eval::Ctx;
use crate::interp::Interp;

/// A permutation of model values: maps each moved model value to its image
/// (fixed points are left out).
pub(super) type Perm = HashMap<Sym, Value>;

/// Evaluate a SYMMETRY definition: the non-identity elements of the group
/// generated by its permutations.
pub(super) fn symmetry_perms(ip: &Arc<Interp>, e: &Expr) -> EResult<Vec<Perm>> {
    let set = ip.eval(e, &Env::default(), &Ctx::NONE)?;
    let mut perms = Vec::new();
    for f in ops::enumerate_normalized(&set)? {
        let m = perm_of(&f)?;
        if !m.is_empty() && !perms.contains(&m) {
            perms.push(m);
        }
    }
    close_under_composition(&mut perms);
    Ok(perms)
}

/// Functions and sets with at most this many elements are compared with
/// their images without building them (`cmp_images`).
const MAX_KEYS: usize = 64;

/// A permutation in a form fast to apply: the moved model values (by
/// symbol id) and their images.
#[derive(Clone)]
pub(super) struct FastPerm(Vec<(u32, Value)>);

impl FastPerm {
    pub(super) fn new(p: &Perm) -> FastPerm {
        FastPerm(p.iter().map(|(k, v)| (k.id(), v.clone())).collect())
    }

    #[inline]
    fn get(&self, m: Sym) -> Option<&Value> {
        let id = m.id();
        self.0.iter().find(|(k, _)| *k == id).map(|(_, v)| v)
    }

    /// The images of the model values `support` (symbol ids) into `out`,
    /// for telling apart the permutations that act differently on them;
    /// false if one is not a model value.
    fn images(&self, support: &[u32], out: &mut Vec<u32>) -> bool {
        out.clear();
        for &id in support {
            out.push(match self.0.iter().find(|(k, _)| *k == id) {
                Some((_, Value::ModelValue(m))) => m.id(),
                Some(_) => return false,
                None => id,
            });
        }
        true
    }

    /// The image of `v` under the permutation, or `None` when `v` contains
    /// no moved model value (so unchanged subvalues are shared, not rebuilt).
    pub(super) fn apply(&self, v: &Value) -> tlx_value::Result<Option<Value>> {
        ops::permute_shared(v, &|m| self.get(m).cloned())
    }
}

/// A permutation, `None` for the identity.
type PermRef<'a> = Option<&'a FastPerm>;

/// `cmp_tlc(p(a), q(b))`, comparing component by component without
/// building the images where their structure follows from `a` and `b`
/// (tuples, records, functions and sets of at most `MAX_KEYS` elements,
/// whose images' order is found by comparing images the same way): the
/// result, and the comparisons that can fail, are those of `cmp_tlc` on the
/// images. Anything else is compared on the built images.
pub(super) fn cmp_images(p: PermRef, a: &Value, q: PermRef, b: &Value) -> tlx_value::Result<Ordering> {
    #[cfg(test)]
    CMP_CALLS.with(|n| n.set(n.get() + 1));
    if a.is_empty_fcn() || b.is_empty_fcn() {
        return cmp_built(p, a, q, b);
    }
    let scalar = |v: &Value| matches!(v, Value::Bool(_) | Value::Int(_) | Value::Str(_) | Value::Interval(..));
    match (a, b) {
        (Value::ModelValue(m), Value::ModelValue(n)) => cmp_tlc(mv_image(p, *m, a), mv_image(q, *n, b)),
        _ if scalar(a) && scalar(b) => cmp_tlc(a, b),
        (Value::Tuple(t), Value::Tuple(u)) => {
            if t.len() != u.len() {
                return Ok(t.len().cmp(&u.len()));
            }
            cmp_seq(t.iter().zip(u.iter()).map(|(x, y)| (p, x, q, y)))
        }
        (Value::Record(r), Value::Record(s)) => {
            if r.len() != s.len() {
                return Ok(r.len().cmp(&s.len()));
            }
            for (x, y) in r.iter().zip(s.iter()) {
                let c = x.0.cmp(&y.0);
                if c != Ordering::Equal {
                    return Ok(c);
                }
            }
            cmp_seq(r.iter().zip(s.iter()).map(|(x, y)| (p, &x.1, q, &y.1)))
        }
        (Value::Fcn(ps, _), Value::Fcn(qs, _)) => {
            if ps.len() != qs.len() {
                return Ok(ps.len().cmp(&qs.len()));
            }
            let c = cmp_sorted(p, &|i| &ps[i].0, Some(&|i| &ps[i].1), q, &|i| &qs[i].0, Some(&|i| &qs[i].1), ps.len(), None)?;
            c.map_or_else(|| cmp_built(p, a, q, b), Ok)
        }
        (Value::Set(xs), Value::Set(ys)) => {
            if xs.len() != ys.len() {
                return Ok(xs.len().cmp(&ys.len()));
            }
            let c = cmp_sorted(p, &|i| &xs[i], None, q, &|i| &ys[i], None, xs.len(), None)?;
            c.map_or_else(|| cmp_built(p, a, q, b), Ok)
        }
        _ => cmp_built(p, a, q, b),
    }
}

/// `cmp_images(p, a, q, b)` where the order of the images under `q` of
/// the elements (keys) of `b` is kept in `qo` (if `b` is a set or function
/// of at most `MAX_KEYS`): for comparing many permutations of `a` with the
/// same `q(b)`, which then finds that order once (and as far as needed).
pub(super) fn cmp_images_with(p: PermRef, a: &Value, q: PermRef, b: &Value, qo: &mut Option<ImageOrder>) -> tlx_value::Result<Ordering> {
    let c = match (a, b) {
        (Value::Fcn(ps, _), Value::Fcn(qs, _)) if ps.len() == qs.len() && !ps.is_empty() && ps.len() <= MAX_KEYS => {
            let kb: Keys = &|i| &qs[i].0;
            let ob = qo.get_or_insert_with(|| ImageOrder::new(q, qs.len(), kb).expect("at most MAX_KEYS"));
            cmp_sorted(p, &|i| &ps[i].0, Some(&|i| &ps[i].1), q, kb, Some(&|i| &qs[i].1), ps.len(), Some(ob))?
        }
        (Value::Set(xs), Value::Set(ys)) if xs.len() == ys.len() && ys.len() <= MAX_KEYS => {
            let kb: Keys = &|i| &ys[i];
            let ob = qo.get_or_insert_with(|| ImageOrder::new(q, ys.len(), kb).expect("at most MAX_KEYS"));
            cmp_sorted(p, &|i| &xs[i], None, q, kb, None, xs.len(), Some(ob))?
        }
        _ => None,
    };
    match c {
        Some(c) => Ok(c),
        None => cmp_images(p, a, q, b),
    }
}

/// `cmp_images` of pairs in order: the first that differs.
fn cmp_seq<'v, 'p>(pairs: impl Iterator<Item = (PermRef<'p>, &'v Value, PermRef<'p>, &'v Value)>) -> tlx_value::Result<Ordering> {
    for (p, x, q, y) in pairs {
        let c = cmp_images(p, x, q, y)?;
        if c != Ordering::Equal {
            return Ok(c);
        }
    }
    Ok(Ordering::Equal)
}

/// The image of the model value `v` (= `m`) under `p`.
fn mv_image<'v>(p: PermRef<'v>, m: Sym, v: &'v Value) -> &'v Value {
    p.and_then(|p| p.get(m)).unwrap_or(v)
}

/// `cmp_tlc` of the built images.
fn cmp_built(p: PermRef, a: &Value, q: PermRef, b: &Value) -> tlx_value::Result<Ordering> {
    let image = |p: PermRef, v: &Value| -> tlx_value::Result<Option<Value>> { p.map_or(Ok(None), |p| p.apply(v)) };
    let (x, y) = (image(p, a)?, image(q, b)?);
    cmp_tlc(x.as_ref().unwrap_or(a), y.as_ref().unwrap_or(b))
}

/// `n` sorted, distinct values (`key(i)`: the keys of a function, the
/// elements of a set).
type Keys<'k, 'v> = &'k dyn Fn(usize) -> &'v Value;

/// `cmp_images` of two functions (with values `va`, `vb`) or sets of `n`
/// elements, which TLC compares element by element in order after their
/// sizes: first their keys, then their values. `None` if there are more
/// than `MAX_KEYS`. `ob`: the order of the images of `kb`, if known (in
/// part).
#[allow(clippy::too_many_arguments)] // two (permutation, keys, values) triples, the size and an order
fn cmp_sorted<'v>(
    p: PermRef,
    ka: Keys<'_, 'v>,
    va: Option<Keys<'_, 'v>>,
    q: PermRef,
    kb: Keys<'_, 'v>,
    vb: Option<Keys<'_, 'v>>,
    n: usize,
    ob: Option<&mut ImageOrder>,
) -> tlx_value::Result<Option<Ordering>> {
    let Some(mut oa) = ImageOrder::new(p, n, ka) else {
        return Ok(None);
    };
    let mut own;
    let ob = match ob {
        Some(o) => o,
        None => {
            let Some(o) = ImageOrder::new(q, n, kb) else {
                return Ok(None);
            };
            own = o;
            &mut own
        }
    };
    for j in 0..n {
        let (i, k) = (oa.at(p, n, ka, j)?, ob.at(q, n, kb, j)?);
        let c = cmp_images(p, ka(i), q, kb(k))?;
        if c != Ordering::Equal {
            return Ok(Some(c));
        }
    }
    if let (Some(va), Some(vb)) = (va, vb) {
        for j in 0..n {
            let c = cmp_images(p, va(oa.src[j] as usize), q, vb(ob.src[j] as usize))?;
            if c != Ordering::Equal {
                return Ok(Some(c));
            }
        }
    }
    Ok(Some(Ordering::Equal))
}

/// The order of the images under a permutation of `n` sorted, distinct
/// values: `src[j]` is the index of the value whose image is the `j`th
/// least, known for `j < known`.
pub(super) struct ImageOrder {
    src: [u8; MAX_KEYS],
    known: usize,
    /// The values in `src[..known]` (bit set).
    used: u64,
}

impl ImageOrder {
    /// `None` if there are more than `MAX_KEYS` values.
    fn new(p: PermRef, n: usize, key: Keys) -> Option<ImageOrder> {
        if n > MAX_KEYS {
            return None;
        }
        let mut o = ImageOrder { src: [0; MAX_KEYS], known: 0, used: 0 };
        for (i, s) in o.src[..n].iter_mut().enumerate() {
            *s = i as u8;
        }
        let Some(p) = p else {
            o.known = n;
            return Some(o);
        };
        // Scalars and model values that the permutation maps among the
        // values (`{n1, n2}`, keys of functions over `Server`): the images
        // are the same values, in the same order.
        for i in 0..n {
            let j = match key(i) {
                Value::ModelValue(m) => match p.get(*m) {
                    None => i,
                    Some(img) => match (0..n).find(|&j| key(j) == img) {
                        Some(j) => j,
                        None => return Some(ImageOrder { src: [0; MAX_KEYS], known: 0, used: 0 }),
                    },
                },
                Value::Bool(_) | Value::Int(_) | Value::Str(_) => i,
                _ => return Some(ImageOrder { src: [0; MAX_KEYS], known: 0, used: 0 }),
            };
            o.src[j] = i as u8;
        }
        o.known = n;
        Some(o)
    }

    /// `src[j]`, found (if not yet known) by selecting the least image of
    /// the values not in `src[..j]`: comparisons usually decide at the
    /// first elements, so the images are not sorted beyond that.
    fn at(&mut self, p: PermRef, n: usize, key: Keys, j: usize) -> tlx_value::Result<usize> {
        if j < self.known {
            return Ok(self.src[j] as usize);
        }
        debug_assert_eq!(j, self.known);
        let mut least: Option<usize> = None;
        for i in (0..n).filter(|&i| self.used & (1u64 << i) == 0) {
            let less = match least {
                None => true,
                Some(m) => cmp_images(p, key(i), p, key(m))? == Ordering::Less,
            };
            if less {
                least = Some(i);
            }
        }
        let i = least.expect("an unused value");
        self.src[j] = i as u8;
        self.used |= 1u64 << i;
        self.known += 1;
        Ok(i)
    }
}

/// The variables of the state `vals` by increasing size (number of nodes;
/// ties by position), which permutations of model values preserve.
pub(super) fn size_order(vals: &[Value]) -> Vec<usize> {
    fn size(v: &Value) -> usize {
        match v {
            Value::Set(es) | Value::Tuple(es) => 1 + es.iter().map(size).sum::<usize>(),
            Value::Record(fs) => 1 + fs.iter().map(|(_, x)| size(x)).sum::<usize>(),
            Value::Fcn(ps, _) => 1 + ps.iter().map(|(k, x)| size(k) + size(x)).sum::<usize>(),
            _ => 1,
        }
    }
    let mut order: Vec<(usize, usize)> = vals.iter().enumerate().map(|(i, v)| (size(v), i)).collect();
    order.sort_unstable();
    order.into_iter().map(|(_, i)| i).collect()
}

/// The SYMMETRY group (without the identity) in the forms the
/// fingerprints use.
#[derive(Clone, Default)]
pub(super) struct Group {
    pub(super) perms: Vec<FastPerm>,
    /// The model values (symbol ids) some permutation moves, sorted.
    moved: Vec<u32>,
    /// Cache keys must not alias another group (or a rebuilt model).
    id: u64,
}

impl Group {
    pub(super) fn new(perms: &[Perm]) -> Group {
        let perms: Vec<FastPerm> = perms.iter().map(FastPerm::new).collect();
        let mut moved: Vec<u32> = perms.iter().flat_map(|p| p.0.iter().map(|(k, _)| *k)).collect();
        moved.sort_unstable();
        moved.dedup();
        static NEXT_ID: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);
        Group { perms, moved, id: NEXT_ID.fetch_add(1, std::sync::atomic::Ordering::Relaxed) }
    }

    pub(super) fn is_empty(&self) -> bool {
        self.perms.is_empty()
    }

    /// The index of the permutation giving the least state (in TLC's value
    /// order, comparing the variables one by one in `order`) of the orbit
    /// of `vals`, or `None` when that is `vals` itself.
    ///
    /// The same choice as TLC's (`TLCStateMut.fingerPrint`), which permutes
    /// the whole state for each permutation and compares it with the least
    /// so far: here a permutation's variables are compared with the least
    /// state's only as far as needed (most permutations lose at the first
    /// variable that differs), mostly without building either image
    /// (`cmp_images`), and permutations that act on the model
    /// values of `vals` like an earlier one (or like the identity) are
    /// skipped since they give the same state.
    pub(super) fn least_perm(&self, vals: &mut StateVals, order: &[usize]) -> EResult<Option<usize>> {
        self.choose_perm(vals, order, false)
    }

    /// VIEW fixes the variable order: cache the expensive first bag's
    /// minimal images, keeping all ties for the rest of the state.
    pub(super) fn least_view_perm(&self, vals: &mut StateVals, order: &[usize]) -> EResult<Option<usize>> {
        self.choose_perm(vals, order, true)
    }

    fn choose_perm(&self, vals: &mut StateVals, order: &[usize], cache_bags: bool) -> EResult<Option<usize>> {
        LEAST_BUF.with(|b| {
            let mut b = b.borrow_mut();
            let LeastBuf { support, key, seen, orders, bags } = &mut *b;
            // Preserve support-based skipping, including which comparisons
            // can report incomparable-value errors. Cache only when every
            // moved atom occurs and the original walk visits all permutations.
            support.clear();
            let dedup = !self.collect_support(vals, order, support);
            // With VIEW the variable order cannot change. Record-key bags
            // are expensive first variables, but many successors share them.
            // Keep every minimal image, then compare the remaining variables
            // to break ties exactly as the original permutation-major walk.
            if let Some((&first, rest)) = order.split_first() {
                let v = vals.get(first);
                if cache_bags && !dedup && self.perms.len() >= 5 && matches!(v, Value::Fcn(ps, _) if !ps.is_empty() && ps.len() <= MAX_KEYS && ps.iter().all(|(k, _)| matches!(k, Value::Record(_)))) {
                    let candidates = bags.candidates(self, v)?;
                    let mut best = candidates[0];
                    orders.clear();
                    orders.resize_with(vals.len(), || None);
                    'candidate: for &pi in &candidates[1..] {
                        let (p, q) = (pi.map(|i| &self.perms[i]), best.map(|i| &self.perms[i]));
                        for &i in rest {
                            let v = vals.get(i);
                            match cmp_images_with(p, v, q, v, &mut orders[i])? {
                                Ordering::Greater => continue 'candidate,
                                Ordering::Equal => {}
                                Ordering::Less => {
                                    best = pi;
                                    orders.iter_mut().for_each(|o| *o = None);
                                    continue 'candidate;
                                }
                            }
                        }
                    }
                    return Ok(best);
                }
            }
            // The moved model values occurring in `vals`: permutations that
            // agree on them give the same state. (Not needed when all occur:
            // the permutations then differ on them.)
            seen.clear();
            // The orders of the elements of the least state's sets and
            // functions (variables), found as they are compared.
            orders.clear();
            orders.resize_with(vals.len(), || None);
            let mut best: Option<usize> = None;
            'perm: for (pi, p) in self.perms.iter().enumerate() {
                // (An image that is not a model value: no shortcut.)
                if dedup && p.images(support, key) {
                    if *key == *support || seen.contains(key) {
                        continue;
                    }
                    seen.push(key.clone());
                }
                let q = best.map(|q| &self.perms[q]);
                for &i in order {
                    let v = vals.get(i);
                    match cmp_images_with(Some(p), v, q, v, &mut orders[i])? {
                        Ordering::Greater => continue 'perm,
                        Ordering::Equal => {}
                        Ordering::Less => {
                            best = Some(pi);
                            orders.iter_mut().for_each(|o| *o = None);
                            continue 'perm;
                        }
                    }
                }
            }
            Ok(best)
        })
    }

    /// Add the moved model values occurring in `vals` to `out` (stopping
    /// when all are found); true if all occur (or a lazy value, not
    /// inspected, may contain them).
    fn collect_support(&self, vals: &mut StateVals, order: &[usize], out: &mut Vec<u32>) -> bool {
        fn walk(v: &Value, moved: &[u32], out: &mut Vec<u32>) -> bool {
            match v {
                Value::ModelValue(m) => {
                    let id = m.id();
                    if moved.binary_search(&id).is_ok() && !out.contains(&id) {
                        out.push(id);
                    }
                    out.len() == moved.len()
                }
                Value::Set(es) | Value::Tuple(es) => es.iter().any(|e| walk(e, moved, out)),
                Value::Record(fs) => fs.iter().any(|(_, e)| walk(e, moved, out)),
                Value::Fcn(ps, _) => ps.iter().any(|(k, e)| walk(k, moved, out) || walk(e, moved, out)),
                Value::LazySet(_) | Value::LazyFcn(_) => true,
                Value::Bool(_) | Value::Int(_) | Value::Str(_) | Value::Interval(..) => false,
            }
        }
        order.iter().any(|&i| walk(vals.get(i), &self.moved, out))
    }
}

/// The values of a state, given or decoded as they are needed.
pub enum StateVals<'a> {
    Given(&'a [Value]),
    /// `decode(i)` is the value of variable `i`; `vals` those decoded so far.
    Decoded {
        vals: Vec<Option<Value>>,
        decode: &'a dyn Fn(usize) -> Value,
    },
}

impl<'a> StateVals<'a> {
    /// The values of the `n` variables decoded by `decode`.
    pub fn decoded(n: usize, decode: &'a dyn Fn(usize) -> Value) -> StateVals<'a> {
        StateVals::Decoded { vals: vec![None; n], decode }
    }

    pub(super) fn len(&self) -> usize {
        match self {
            StateVals::Given(v) => v.len(),
            StateVals::Decoded { vals, .. } => vals.len(),
        }
    }

    fn get(&mut self, i: usize) -> &Value {
        match self {
            StateVals::Given(v) => &v[i],
            StateVals::Decoded { vals, decode } => vals[i].get_or_insert_with(|| decode(i)),
        }
    }
}

/// A bounded per-thread cache of the permutations giving the least image
/// of a first-variable record-key bag. Entries retain the Arc: pointer keys
/// cannot be reused for different values. Identity is first, followed by the
/// group's original order, so ties preserve TLC's representative choice.
struct BagEntry {
    group: u64,
    bag: Arc<[(Value, Value)]>,
    candidates: Arc<[Option<usize>]>,
    bytes: usize,
}

#[derive(Default)]
struct BagCache {
    slots: Vec<Option<BagEntry>>,
    bytes: usize,
    published: tlx_runtime::cache_mem::Published,
}

impl BagCache {
    const SLOTS: usize = 1024;

    fn candidates(&mut self, group: &Group, value: &Value) -> EResult<Arc<[Option<usize>]>> {
        let Value::Fcn(bag, _) = value else { unreachable!("record-key bag") };
        let budget = (tlx_runtime::cache_mem::share() / 8).min(4 << 20);
        if self.bytes > budget {
            self.slots.clear();
            self.bytes = 0;
            self.published.update(0);
        }
        let hash = tlx_base::hash::fmix64(Arc::as_ptr(bag) as *const () as usize as u64 ^ group.id.rotate_left(17));
        let slot = hash as usize & (Self::SLOTS - 1);
        if let Some(Some(e)) = self.slots.get(slot) {
            if e.group == group.id && Arc::ptr_eq(&e.bag, bag) {
                return Ok(e.candidates.clone());
            }
        }
        let mut candidates = vec![None];
        let mut best = None;
        let mut order = None;
        for (i, p) in group.perms.iter().enumerate() {
            match cmp_images_with(Some(p), value, best.map(|i| &group.perms[i]), value, &mut order)? {
                Ordering::Greater => {}
                Ordering::Equal => candidates.push(Some(i)),
                Ordering::Less => {
                    candidates.clear();
                    candidates.push(Some(i));
                    best = Some(i);
                    order = None;
                }
            }
        }
        let candidates: Arc<[Option<usize>]> = candidates.into();
        // Conservatively count the retained bag too, even when the Dyn
        // interner or another state already owns it. Stop counting at the
        // budget: a large entry is evaluated but never retained.
        fn retained(v: &Value, cap: usize) -> usize {
            let mut bytes = std::mem::size_of::<Value>();
            match v {
                Value::Tuple(es) | Value::Set(es) => {
                    for e in es.iter() {
                        bytes = bytes.saturating_add(retained(e, cap));
                        if bytes > cap {
                            break;
                        }
                    }
                }
                Value::Record(fs) => {
                    for (_, e) in fs.iter() {
                        bytes = bytes.saturating_add(std::mem::size_of::<Sym>() + retained(e, cap));
                        if bytes > cap {
                            break;
                        }
                    }
                }
                Value::Fcn(ps, _) => {
                    for (k, v) in ps.iter() {
                        bytes = bytes.saturating_add(retained(k, cap)).saturating_add(retained(v, cap));
                        if bytes > cap {
                            break;
                        }
                    }
                }
                Value::LazySet(_) | Value::LazyFcn(_) => return cap.saturating_add(1),
                _ => {}
            }
            bytes
        }
        let bytes = retained(value, budget).saturating_add(std::mem::size_of_val(&*candidates));
        let table_bytes = Self::SLOTS * std::mem::size_of::<Option<BagEntry>>();
        if bytes.saturating_add(table_bytes) <= budget {
            if self.slots.is_empty() {
                self.slots.resize_with(Self::SLOTS, || None);
                self.bytes = table_bytes;
            }
            let old = self.slots[slot].take().map_or(0, |e| e.bytes);
            self.bytes -= old;
            if self.bytes.saturating_add(bytes) > budget {
                self.slots.iter_mut().for_each(|e| *e = None);
                self.bytes = table_bytes;
            }
            self.slots[slot] = Some(BagEntry { group: group.id, bag: bag.clone(), candidates: candidates.clone(), bytes });
            self.bytes += bytes;
            self.published.update(self.bytes);
        }
        Ok(candidates)
    }
}

/// Scratch buffers of `Group::least_perm`.
#[derive(Default)]
struct LeastBuf {
    support: Vec<u32>,
    key: Vec<u32>,
    seen: Vec<Vec<u32>>,
    orders: Vec<Option<ImageOrder>>,
    bags: BagCache,
}

thread_local! {
    static LEAST_BUF: std::cell::RefCell<LeastBuf> = std::cell::RefCell::default();
}

/// The fingerprint of a sequence of fingerprints.
pub(super) fn combine_fps(fps: &[u64]) -> EResult<u64> {
    let mut fp = tlx_value::fingerprint::Fingerprinter::new();
    for &h in fps {
        fp.add(&Value::Int(h as i64))?;
    }
    Ok(fp.finish())
}

/// The permutation a function over model values denotes.
fn perm_of(f: &Value) -> EResult<Perm> {
    let mut m = HashMap::new();
    for k in ops::enumerate_normalized(&ops::domain(f)?)? {
        let Value::ModelValue(sym) = k else {
            return Err(EvalError::new(format!("SYMMETRY permutations must map model values, found {k}")));
        };
        let img = ops::apply(f, &k)?;
        if img != k {
            m.insert(sym, img);
        }
    }
    Ok(m)
}

/// `p ∘ q`.
fn compose(p: &Perm, q: &Perm) -> Perm {
    let mut r = HashMap::new();
    let keys: HashSet<Sym> = p.keys().chain(q.keys()).copied().collect();
    for k in keys {
        let mid = q.get(&k).cloned().unwrap_or(Value::ModelValue(k));
        let img = match &mid {
            Value::ModelValue(m) => p.get(m).cloned().unwrap_or(mid.clone()),
            _ => mid.clone(),
        };
        if img != Value::ModelValue(k) {
            r.insert(k, img);
        }
    }
    r
}

/// The non-identity elements of the group the permutations `gens`
/// generate.
pub(super) fn closure(gens: Vec<Perm>) -> Vec<Perm> {
    let mut perms: Vec<Perm> = Vec::new();
    for g in gens {
        if !g.is_empty() && !perms.contains(&g) {
            perms.push(g);
        }
    }
    close_under_composition(&mut perms);
    perms
}

/// Add every composition of a generator (the initial elements) with a group
/// element until closed. TLC uses the generated group
/// (MVPerms.permutationSubgroup), without the identity.
fn close_under_composition(perms: &mut Vec<Perm>) {
    let generators = perms.len();
    let mut start = 0;
    loop {
        let end = perms.len();
        for i in 0..generators {
            for j in start..end {
                let c = compose(&perms[i], &perms[j]);
                if !c.is_empty() && !perms.contains(&c) {
                    perms.push(c);
                }
            }
        }
        if perms.len() == end {
            break;
        }
        start = end;
    }
}

#[cfg(test)]
thread_local! {
    static CMP_CALLS: std::cell::Cell<usize> = const { std::cell::Cell::new(0) };
}

#[cfg(test)]
mod tests {
    use super::*;

    fn group() -> (Group, [Sym; 3]) {
        let atoms = [Sym::new("bag_a"), Sym::new("bag_b"), Sym::new("bag_c")];
        let mut perms = Vec::new();
        for a in 0..3 {
            for b in 0..3 {
                if a == b {
                    continue;
                }
                let c = 3 - a - b;
                let img = [a, b, c];
                if img == [0, 1, 2] {
                    continue;
                }
                perms.push(
                    atoms.iter().enumerate().filter_map(|(i, &s)| (i != img[i]).then_some((s, Value::ModelValue(atoms[img[i]])))).collect(),
                );
            }
        }
        (Group::new(&perms), atoms)
    }

    fn bag(atoms: &[Sym; 3]) -> Value {
        let field = Sym::new("src");
        Value::fcn_from_pairs(vec![
            (Value::record(vec![(field, Value::ModelValue(atoms[0]))]), Value::Int(1)),
            (Value::record(vec![(field, Value::ModelValue(atoms[1]))]), Value::Int(1)),
        ])
        .unwrap()
    }

    fn brute(g: &Group, vals: &[Value], order: &[usize]) -> Option<usize> {
        let mut best = vals.to_vec();
        let mut pi = None;
        for (i, p) in g.perms.iter().enumerate() {
            let image: Vec<_> = vals.iter().map(|v| p.apply(v).unwrap().unwrap_or_else(|| v.clone())).collect();
            let mut cmp = Ordering::Equal;
            for &j in order {
                cmp = cmp_tlc(&image[j], &best[j]).unwrap();
                if cmp != Ordering::Equal {
                    break;
                }
            }
            if cmp == Ordering::Less {
                best = image;
                pi = Some(i);
            }
        }
        pi
    }

    #[test]
    fn record_bag_candidates_keep_later_variable_ties() {
        let (g, atoms) = group();
        let net = bag(&atoms);
        for tail in atoms {
            let vals = [net.clone(), Value::ModelValue(tail)];
            assert_eq!(g.least_view_perm(&mut StateVals::Given(&vals), &[0, 1]).unwrap(), brute(&g, &vals, &[0, 1]));
        }
        let (other, _) = group();
        let mut other = other;
        other.perms.reverse();
        let vals = [net, Value::ModelValue(atoms[1])];
        assert_eq!(other.least_view_perm(&mut StateVals::Given(&vals), &[0, 1]).unwrap(), brute(&other, &vals, &[0, 1]));
    }

    #[test]
    fn record_bag_candidates_match_full_images() {
        let (g, atoms) = group();
        let mut keys = Vec::new();
        for &src in &atoms {
            for &dst in &atoms {
                if src != dst {
                    keys.push(Value::record(vec![
                        (Sym::new("src"), Value::ModelValue(src)),
                        (Sym::new("dst"), Value::ModelValue(dst)),
                        (Sym::new("payload"), Value::tuple(vec![Value::Int(2), Value::ModelValue(src)])),
                    ]));
                }
            }
        }
        for mask in 0..1usize << keys.len() {
            let bag = Value::fcn_from_pairs(
                keys.iter()
                    .enumerate()
                    .filter_map(|(i, k)| (mask & (1 << i) != 0).then_some((k.clone(), Value::Int((i % 3) as i64))))
                    .collect(),
            )
            .unwrap();
            for &tail in &atoms {
                let vals = [bag.clone(), Value::ModelValue(tail), Value::Int(1)];
                for order in [[0, 1, 2], [2, 0, 1], [1, 0, 2]] {
                    assert_eq!(
                        g.least_view_perm(&mut StateVals::Given(&vals), &order).unwrap(),
                        brute(&g, &vals, &order),
                        "mask={mask}, order={order:?}"
                    );
                }
            }
        }
    }

    #[test]
    fn nonidentity_bag_minima_are_decided_by_the_second_variable() {
        let (g, atoms) = group();
        let net = bag(&[atoms[1], atoms[2], atoms[0]]);
        let candidates = BagCache::default().candidates(&g, &net).unwrap();
        assert_eq!(candidates.len(), 2);
        assert!(candidates.iter().all(Option::is_some), "identity must lose on the first variable");
        let mut winners = Vec::new();
        for tail in [atoms[1], atoms[2]] {
            let all = Value::set_from(atoms.iter().copied().map(Value::ModelValue).collect()).unwrap();
            let vals = [net.clone(), Value::ModelValue(tail), all];
            let expected = brute(&g, &vals, &[0, 1, 2]);
            assert!(expected.is_some());
            assert_eq!(g.least_view_perm(&mut StateVals::Given(&vals), &[0, 1, 2]).unwrap(), expected);
            winners.push(expected);
        }
        assert_ne!(winners[0], winners[1], "the second variable must break the first-variable tie");
    }

    #[test]
    fn incomparable_bag_keys_report_the_original_comparison_error() {
        let (g, atoms) = group();
        let rec = |v| Value::record(vec![(Sym::new("src"), v)]);
        for pairs in [
            vec![(Value::Int(1), Value::Int(0)), (rec(Value::ModelValue(atoms[0])), Value::Int(0))],
            vec![(rec(Value::Int(1)), Value::Int(0)), (rec(Value::Bool(true)), Value::Int(0))],
        ] {
            // Intentionally incomparable keys cannot be normalized into a
            // function. Feed them directly to the comparison boundary to
            // check both the rejected-cache and eligible-record-key paths.
            let bag = Value::Fcn(pairs.into(), tlx_value::FcnDom::Enumerated);
            let vals = [bag, Value::set_from(atoms.iter().copied().map(Value::ModelValue).collect()).unwrap()];
            let old = g.least_perm(&mut StateVals::Given(&vals), &[0, 1]).unwrap_err();
            let cached = g.least_view_perm(&mut StateVals::Given(&vals), &[0, 1]).unwrap_err();
            assert_eq!(cached.message, old.message);
            assert_eq!(cached.kind, old.kind);
        }
        let no_atoms = [Value::Fcn(
            vec![(rec(Value::Int(1)), Value::Int(0)), (rec(Value::Bool(true)), Value::Int(0))].into(),
            tlx_value::FcnDom::Enumerated,
        )];
        assert_eq!(g.least_perm(&mut StateVals::Given(&no_atoms), &[0]).unwrap(), None);
        assert_eq!(g.least_view_perm(&mut StateVals::Given(&no_atoms), &[0]).unwrap(), None);
    }

    #[test]
    fn symmetry_without_view_keeps_the_uncached_comparison_path() {
        let (g, atoms) = group();
        let vals = [bag(&atoms), Value::ModelValue(atoms[0])];
        CMP_CALLS.with(|n| n.set(0));
        g.least_perm(&mut StateVals::Given(&vals), &[0, 1]).unwrap();
        let cold = CMP_CALLS.with(|n| n.replace(0));
        g.least_perm(&mut StateVals::Given(&vals), &[0, 1]).unwrap();
        let warm = CMP_CALLS.with(|n| n.get());
        assert_eq!(warm, cold, "without VIEW, bag comparison must stay uncached");
    }

    #[test]
    fn record_bag_comparison_errors_match_the_original_walk() {
        let (g, atoms) = group();
        let all = Value::set_from(atoms.iter().copied().map(Value::ModelValue).collect()).unwrap();
        let choices =
            [Value::Bool(false), Value::Bool(true), Value::Int(0), Value::Int(1), Value::tuple(vec![]), Value::tuple(vec![Value::Int(0)])];
        for mask in 1..64u32 {
            let mut pairs = Vec::new();
            let mut bit = 0;
            for &src in &atoms {
                for &dst in &atoms {
                    if src == dst {
                        continue;
                    }
                    if mask & (1 << bit) != 0 {
                        pairs.push((
                            Value::record(vec![(Sym::new("src"), Value::ModelValue(src)), (Sym::new("dst"), Value::ModelValue(dst))]),
                            Value::Int(1),
                        ));
                    }
                    bit += 1;
                }
            }
            let net = Value::fcn_from_pairs(pairs).unwrap();
            for a in &choices {
                for b in &choices {
                    for c in &choices {
                        let tail = Value::fcn_from_pairs(
                            atoms.into_iter().zip([a.clone(), b.clone(), c.clone()]).map(|(k, v)| (Value::ModelValue(k), v)).collect(),
                        )
                        .unwrap();
                        let vals = [net.clone(), tail, all.clone()];
                        let old = g.least_perm(&mut StateVals::Given(&vals), &[0, 1, 2]);
                        let cached = g.least_view_perm(&mut StateVals::Given(&vals), &[0, 1, 2]);
                        assert_eq!(old.is_err(), cached.is_err(), "mask={mask}, vals={vals:?}, old={old:?}, cached={cached:?}");
                    }
                }
            }
        }
    }

    #[test]
    fn repeated_record_bag_reuses_permutation_comparisons() {
        let (g, atoms) = group();
        let net = bag(&atoms);
        let all = Value::set_from(atoms.iter().copied().map(Value::ModelValue).collect()).unwrap();
        let vals = [net.clone(), Value::ModelValue(atoms[0]), all.clone()];
        CMP_CALLS.with(|n| n.set(0));
        g.least_view_perm(&mut StateVals::Given(&vals), &[0, 1, 2]).unwrap();
        let cold = CMP_CALLS.with(|n| n.replace(0));
        let vals = [net, Value::ModelValue(atoms[1]), all];
        assert_eq!(g.least_view_perm(&mut StateVals::Given(&vals), &[0, 1, 2]).unwrap(), brute(&g, &vals, &[0, 1, 2]));
        let warm = CMP_CALLS.with(|n| n.get());
        assert!(warm * 3 < cold, "repeated bag comparisons: cold={cold}, warm={warm}");
    }
}
